from pathlib import Path


def replace_once(path, old, new):
    p=Path(path); text=p.read_text()
    if old not in text: raise SystemExit(f'anchor missing in {path}: {old[:140]}')
    p.write_text(text.replace(old,new,1))

# Galaxy identity is a research context; xStock token provenance remains Solana.
replace_once('src/lib/field/types.ts',
    'export type GalaxyId = "galaxy-zero" | "fomo" | "solana-core" | "pump-fun" | "pons";',
    'export type GalaxyId = "galaxy-zero" | "fomo" | "afterbell" | "solana-core" | "pump-fun" | "pons";')

p=Path('src/lib/field/galaxies.ts'); text=p.read_text()
fomo='  {id:"fomo",name:"Fomo",ecosystem:"Trader research galaxy",status:"populated",seed:1299,accent:"#6f80ff",description:"The cached Fomo all-time top 50 become public-wallet stars. Enter a trader to study mapped token positions and retained trade evidence.",coverage:"fomoapi.io all-time leaderboard as reported + retained A Bulls App public-chain evidence",sources:["fomoapi.io","A Bulls App indexed public-chain evidence"]},\n'
after='  {id:"afterbell",name:"Afterbell",ecosystem:"Tokenized equities research galaxy",status:"populated",seed:1974,accent:"#ead49a",description:"A sibling research galaxy for Solana tokenized equities. xStock PLANETS keep Solana provenance while venue-reported market context stays separately labeled.",coverage:"DexScreener venue-reported Solana xStock market context + A Bulls retained public-chain evidence when available",sources:["DexScreener venue-reported","A Bulls App indexed Solana evidence"]},\n'
if after.strip() not in text:
    if fomo not in text: raise SystemExit('galaxies fomo anchor missing')
    text=text.replace(fomo,fomo+after,1)
text=text.replace('export const GALAXIES = GALAXY_REGISTRY.filter(item=>item.id==="galaxy-zero"||item.id==="fomo") as readonly GalaxyDefinition[];', 'export const GALAXIES = GALAXY_REGISTRY.filter(item=>item.id==="galaxy-zero"||item.id==="fomo"||item.id==="afterbell") as readonly GalaxyDefinition[];',1)
text=text.replace('export const GALAXY_CHAIN_LABEL: Record<GalaxyId, string> = {"galaxy-zero":"UNIVERSE MAP",fomo:"TRADER RESEARCH","solana-core":"SOLANA","pump-fun":"SOLANA",pons:"ROBINHOOD CHAIN"};', 'export const GALAXY_CHAIN_LABEL: Record<GalaxyId, string> = {"galaxy-zero":"UNIVERSE MAP",fomo:"TRADER RESEARCH",afterbell:"SOLANA TOKENIZED EQUITIES","solana-core":"SOLANA","pump-fun":"SOLANA",pons:"ROBINHOOD CHAIN"};',1)
content_anchor='  fomo:Object.freeze({durable:["wallet","token"],transient:["trade"],excludes:["program","nft"]}),\n'
if '  afterbell:Object.freeze(' not in text:
    if content_anchor not in text: raise SystemExit('galaxy content anchor missing')
    text=text.replace(content_anchor,content_anchor+'  afterbell:Object.freeze({durable:["token","wallet"],transient:["trade"],excludes:["program","nft"]}),\n',1)
p.write_text(text)

# Galaxy Zero now contains two explorable research galaxies while origin chips remain unchanged.
p=Path('src/lib/field/synthetic-universe.ts'); text=p.read_text()
text=text.replace('if(galaxy.id==="fomo"||galaxy.id==="pons"||galaxy.id==="pump-fun")return decorativeGalaxy(galaxy,count,seed);','if(galaxy.id==="fomo"||galaxy.id==="afterbell"||galaxy.id==="pons"||galaxy.id==="pump-fun")return decorativeGalaxy(galaxy,count,seed);',1)
text=text.replace('export const GALAXY_ZERO_CENTERS:readonly [number,number,number][]=[[0,0,0]];','export const GALAXY_ZERO_CENTERS:readonly [number,number,number][]=[[-24,0,0],[24,0,0]];',1)
text=text.replace('const random=mulberry(seed),bounded=Math.max(600,Math.min(6000,Math.trunc(count))),definitions=[getGalaxy("fomo")],centers=GALAXY_ZERO_CENTERS,particles:FieldParticle[]=[],perGalaxy=Math.floor(bounded*.78/definitions.length);','const random=mulberry(seed),bounded=Math.max(600,Math.min(6000,Math.trunc(count))),definitions=[getGalaxy("fomo"),getGalaxy("afterbell")],centers=GALAXY_ZERO_CENTERS,particles:FieldParticle[]=[],perGalaxy=Math.floor(bounded*.78/definitions.length);',1)
text=text.replace('coverageStatement:"Galaxy Zero maps Fomo. Generic Solana evidence and retained launch-origin provenance remain available through search, Replay, Evidence, and the Index rather than separate public galaxies."','coverageStatement:"Galaxy Zero maps Fomo and Afterbell as sibling research galaxies. Token PLANETS keep their immutable chain/launch provenance; generic Solana evidence remains available through search, Replay, Evidence, and the Index."',1)
p.write_text(text)

client='''export type AfterbellPair = {\n  mint:string; symbol:string; priceUsd:number; change24h:number|null; volume24h:number|null; liquidityUsd:number|null;\n};\nexport type AfterbellPlanetRecord = AfterbellPair & { name:string; cashSymbol:string; issuer:string; source:"DexScreener venue-reported"; observedAt:number; };\nexport type AfterbellGalaxyData = { ok:boolean; coverage:"fresh"|"degraded"|"empty"; planets:readonly AfterbellPlanetRecord[]; disclosure:string; source:"DexScreener venue-reported"; };\n\ntype CatalogItem={symbol:string;name:string;cashSymbol:string;issuer:string;mintHint?:string};\nconst CATALOG:readonly CatalogItem[]=[\n  {symbol:"AAPLx",name:"Apple",cashSymbol:"AAPL",issuer:"xStocks"},\n  {symbol:"NVDAx",name:"NVIDIA",cashSymbol:"NVDA",issuer:"xStocks",mintHint:"Xsc9qvGR1efVDFGLrVsmkzv3qi45LTBjeUKSPmx9qEh"},\n  {symbol:"TSLAx",name:"Tesla",cashSymbol:"TSLA",issuer:"xStocks",mintHint:"XsDoVfqeBukxuZHWhdvWHBhgEHjGNst4MLodqsJHzoB"},\n  {symbol:"MSFTx",name:"Microsoft",cashSymbol:"MSFT",issuer:"xStocks",mintHint:"XspzcW1PRtgf6Wj92HCiZdjzKCyFekVD8P5Ueh3dRMX"},\n  {symbol:"AMZNx",name:"Amazon",cashSymbol:"AMZN",issuer:"xStocks"},\n  {symbol:"SPYx",name:"S&P 500",cashSymbol:"SPY",issuer:"xStocks"},\n  {symbol:"QQQx",name:"Nasdaq-100",cashSymbol:"QQQ",issuer:"xStocks"},\n  {symbol:"CRCLx",name:"Circle",cashSymbol:"CRCL",issuer:"xStocks"},\n];\nconst SOURCE="DexScreener venue-reported" as const,CACHE_MS=60_000;\nlet cached:{at:number;value:AfterbellGalaxyData}|null=null;\nconst finite=(value:unknown)=>Number.isFinite(Number(value))?Number(value):null;\nconst record=(value:unknown)=>value&&typeof value==="object"?value as Record<string,unknown>:{};\n\nexport function selectAfterbellPair(symbol:string,pairs:readonly unknown[]):AfterbellPair|null{\n  const candidates=pairs.map(pair=>record(pair)).filter(pair=>String(pair.chainId??"").toLowerCase()==="solana"&&String(record(pair.baseToken).symbol??"").toLowerCase()===symbol.toLowerCase()).map(pair=>{\n    const base=record(pair.baseToken),mint=String(base.address??"").trim(),priceUsd=finite(pair.priceUsd),change24h=finite(record(pair.priceChange).h24),volume24h=finite(record(pair.volume).h24),liquidityUsd=finite(record(pair.liquidity).usd);\n    return mint&&priceUsd!=null&&priceUsd>0?{mint,symbol:String(base.symbol??symbol),priceUsd,change24h,volume24h,liquidityUsd}:null;\n  }).filter((item):item is AfterbellPair=>Boolean(item));\n  candidates.sort((a,b)=>(b.liquidityUsd??0)-(a.liquidityUsd??0)||(b.volume24h??0)-(a.volume24h??0));return candidates[0]??null;\n}\nasync function loadPairs(item:CatalogItem,fetchImpl:typeof fetch){\n  const urls:string[]=[];if(item.mintHint)urls.push(`https://api.dexscreener.com/latest/dex/tokens/${encodeURIComponent(item.mintHint)}`);urls.push(`https://api.dexscreener.com/latest/dex/search?q=${encodeURIComponent(item.symbol)}`);\n  for(const url of urls){try{const response=await fetchImpl(url,{headers:{accept:"application/json"}});if(!response.ok)continue;const body=record(await response.json()),pairs=Array.isArray(body.pairs)?body.pairs:[],selected=selectAfterbellPair(item.symbol,pairs);if(selected)return selected;}catch{} }return null;\n}\nexport async function getAfterbellGalaxy(fetchImpl:typeof fetch=fetch):Promise<AfterbellGalaxyData>{\n  const now=Date.now();if(cached&&now-cached.at<CACHE_MS)return cached.value;\n  const settled=await Promise.allSettled(CATALOG.map(async item=>{const pair=await loadPairs(item,fetchImpl);return pair?{...pair,name:item.name,cashSymbol:item.cashSymbol,issuer:item.issuer,source:SOURCE,observedAt:Date.now()}:null;})),planets=settled.flatMap(result=>result.status==="fulfilled"&&result.value?[result.value]:[]),failures=settled.filter(result=>result.status==="rejected").length,coverage=planets.length===CATALOG.length?"fresh":planets.length?"degraded":"empty",value:AfterbellGalaxyData={ok:planets.length>0,coverage,planets,source:SOURCE,disclosure:planets.length?`${planets.length} of ${CATALOG.length} Afterbell xStock PLANETS currently have finite Solana venue prices. Values are DexScreener venue-reported; missing coverage is not zero, and token provenance remains Solana.`:failures?"Afterbell venue reads are temporarily unavailable. No token or price was fabricated.":"No qualifying Solana xStock venue pairs are currently available. Missing coverage is not zero."};\n  cached={at:now,value};return value;\n}\nexport const __afterbellClientContract=Object.freeze({readOnly:true,execution:false,custody:false,source:SOURCE,catalogSize:CATALOG.length,cacheMs:CACHE_MS});\n'''
Path('src/lib/universe-data/afterbell-client.ts').write_text(client)

builder='''import type { FieldParticle, UniverseSnapshot } from "./types";\nimport { canonicalUniverseId } from "./galaxies";\nimport type { AfterbellGalaxyData } from "@/lib/universe-data/afterbell-client";\n\nconst POSITIONS:readonly [number,number,number][]=[[-34,2,-8],[-23,9,17],[-9,-2,-25],[8,7,24],[23,-4,-15],[35,6,7],[-5,16,4],[14,-13,2]];\nconst finitePositive=(value:number|null)=>value!=null&&Number.isFinite(value)&&value>0;\nexport function buildAfterbellGalaxySnapshot(data:AfterbellGalaxyData):UniverseSnapshot{\n  const particles:FieldParticle[]=data.planets.filter(item=>item.mint&&finitePositive(item.priceUsd)).slice(0,POSITIONS.length).map((item,index)=>({id:canonicalUniverseId("planet",item.mint,"solana-core"),kind:"token",cosmicKind:"planet",originGalaxyId:"solana-core",verificationState:"provider-reported",observedAt:item.observedAt,category:"swap",magnitudeBand:Math.max(.38,Math.min(1,.5+Math.log10(Math.max(1,item.liquidityUsd??1))/14)),position:POSITIONS[index],source:item.source,metadata:{mint:item.mint,symbol:item.symbol,name:item.name,cashSymbol:item.cashSymbol,issuer:item.issuer,priceUsd:item.priceUsd,change24h:item.change24h,volume24h:item.volume24h,liquidityUsd:item.liquidityUsd,afterbellEquity:true,providerReported:true,researchGalaxyId:"afterbell",afterbellDeepLink:"/afterbell/"}}));\n  const times=particles.map(item=>item.observedAt).filter(Number.isFinite),windowEnd=times.length?Math.max(...times):Date.now(),windowStart=times.length?Math.min(...times):windowEnd;\n  return{galaxyId:"afterbell",windowStart,windowEnd,observedEventCount:0,samplingPolicy:"bounded xStock venue snapshot; provider-reported market context only",coverageStatement:data.disclosure,sources:[data.source],particles};\n}\n'''
Path('src/lib/field/afterbell-galaxy.ts').write_text(builder)

test='''import test from "node:test";\nimport assert from "node:assert/strict";\nimport { buildAfterbellGalaxySnapshot } from "./afterbell-galaxy";\nimport { selectAfterbellPair, type AfterbellGalaxyData } from "@/lib/universe-data/afterbell-client";\n\ntest("Afterbell PLANETS preserve Solana provenance while the snapshot stays in the Afterbell research galaxy",()=>{\n  const data:AfterbellGalaxyData={ok:true,coverage:"fresh",source:"DexScreener venue-reported",disclosure:"fixture",planets:[{mint:"MintAfterbell1",symbol:"NVDAx",name:"NVIDIA",cashSymbol:"NVDA",issuer:"xStocks",priceUsd:123.45,change24h:1.2,volume24h:5_000_000,liquidityUsd:2_000_000,source:"DexScreener venue-reported",observedAt:1_789_000_000_000}]};\n  const snapshot=buildAfterbellGalaxySnapshot(data);assert.equal(snapshot.galaxyId,"afterbell");assert.equal(snapshot.particles.length,1);assert.equal(snapshot.observedEventCount,0);const planet=snapshot.particles[0];assert.equal(planet.cosmicKind,"planet");assert.equal(planet.originGalaxyId,"solana-core");assert.equal(planet.verificationState,"provider-reported");assert.equal(planet.metadata?.researchGalaxyId,"afterbell");assert.equal(planet.metadata?.mint,"MintAfterbell1");\n});\n\ntest("Afterbell pair selection rejects other chains and ranks exact-symbol Solana venues by liquidity",()=>{\n  const pair=selectAfterbellPair("NVDAx",[{chainId:"base",baseToken:{symbol:"NVDAx",address:"base"},priceUsd:"10",liquidity:{usd:9999999}},{chainId:"solana",baseToken:{symbol:"OTHER",address:"bad"},priceUsd:"10",liquidity:{usd:9999999}},{chainId:"solana",baseToken:{symbol:"NVDAx",address:"low"},priceUsd:"100",liquidity:{usd:100}},{chainId:"solana",baseToken:{symbol:"NVDAx",address:"high"},priceUsd:"101",liquidity:{usd:1000}}]);\n  assert.equal(pair?.mint,"high");assert.equal(pair?.priceUsd,101);\n});\n'''
Path('src/lib/field/afterbell-galaxy.test.ts').write_text(test)

# Wire the new data source into FieldOS without touching the renderer.
