text=text.replace('import { getFomoGalaxy, getFomoTraderSystem } from "@/lib/universe-data/fomo-client";','import { getFomoGalaxy, getFomoTraderSystem } from "@/lib/universe-data/fomo-client";\nimport { getAfterbellGalaxy } from "@/lib/universe-data/afterbell-client";',1)
text=text.replace('import { buildFomoGalaxySnapshot } from "./fomo-galaxy";','import { buildFomoGalaxySnapshot } from "./fomo-galaxy";\nimport { buildAfterbellGalaxySnapshot } from "./afterbell-galaxy";',1)
needle='if(id==="fomo"){const data=await getFomoGalaxy();if(this.#destroyed||this.queryActive||seq!==this.#snapshotSeq||id!==this.galaxy.id)return;const snapshot=data.ok?buildFomoGalaxySnapshot(data):null;this.#live=snapshot&&snapshot.particles.length?snapshot:null;this.dataStatus={store:"d1",coverage:data.coverage==="fresh"?"fresh":data.coverage,circuitBreaker:null,disclosure:data.disclosure};this.#applySky();this.#emit();return;}'
afterhydrate=needle+'if(id==="afterbell"){const data=await getAfterbellGalaxy();if(this.#destroyed||this.queryActive||seq!==this.#snapshotSeq||id!==this.galaxy.id)return;const snapshot=data.ok?buildAfterbellGalaxySnapshot(data):null;this.#live=snapshot&&snapshot.particles.length?snapshot:null;this.dataStatus={store:"memory-fallback",coverage:data.coverage,circuitBreaker:null,disclosure:data.disclosure};this.#applySky();this.#emit();return;}'
if needle not in text: raise SystemExit('field-os Fomo hydration anchor missing')
text=text.replace(needle,afterhydrate,1);p.write_text(text)

