old='test("Galaxy Zero exposes only Fomo while retired launch origins remain provenance-compatible",()=>{const zero=getGalaxy("galaxy-zero");assert.equal(zero.status,"populated");assert.equal(zero.seed,861);assert.equal(isPopulatedGalaxy("galaxy-zero"),true);assert.equal(isPopulatedGalaxy("fomo"),true);assert.equal(isPopulatedGalaxy("solana-core"),false);assert.equal(isPopulatedGalaxy("pump-fun"),false);assert.equal(isPopulatedGalaxy("pons"),false);assert.equal(getGalaxy("fomo").ecosystem,"Trader research galaxy");assert.equal(getGalaxy("pump-fun").status,"staging");assert.equal(getGalaxy("pons").status,"staging");assert.equal(GALAXIES.length,2);assert.deepEqual(GALAXY_ORIGIN_CHIPS,[{id:"galaxy-zero",label:"ZERO"},{id:"fomo",label:"FOMO"}]);assert.deepEqual(GALAXY_CONTENT.pons.excludes,["nft"]);const map=createGalaxySnapshot(zero,900);assert.equal(map.observedEventCount,0);assert.deepEqual(new Set(map.particles.flatMap(p=>typeof p.metadata?.targetGalaxyId==="string"?[p.metadata.targetGalaxyId]:[])),new Set(["fomo"]));assert.equal(map.particles.some(p=>["wallet","transaction","token","nft","program"].includes(p.kind)),false);assert.ok(GALAXY_ZERO_CAMERA_DISTANCE>=190);assert.equal(GALAXY_ZERO_CENTERS.length,1);assert.ok(GALAXY_ZERO_CENTERS.every(([x,y])=>Math.abs(x)<=30&&Math.abs(y)<=25));});'
new='test("Galaxy Zero exposes Fomo and Afterbell as research galaxies while launch-origin chips stay provenance-compatible",()=>{const zero=getGalaxy("galaxy-zero");assert.equal(zero.status,"populated");assert.equal(zero.seed,861);assert.equal(isPopulatedGalaxy("galaxy-zero"),true);assert.equal(isPopulatedGalaxy("fomo"),true);assert.equal(isPopulatedGalaxy("afterbell"),true);assert.equal(isPopulatedGalaxy("solana-core"),false);assert.equal(isPopulatedGalaxy("pump-fun"),false);assert.equal(isPopulatedGalaxy("pons"),false);assert.equal(getGalaxy("fomo").ecosystem,"Trader research galaxy");assert.equal(getGalaxy("afterbell").ecosystem,"Tokenized equities research galaxy");assert.equal(getGalaxy("pump-fun").status,"staging");assert.equal(getGalaxy("pons").status,"staging");assert.equal(GALAXIES.length,3);assert.deepEqual(GALAXY_ORIGIN_CHIPS,[{id:"galaxy-zero",label:"ZERO"},{id:"fomo",label:"FOMO"}]);assert.deepEqual(GALAXY_CONTENT.pons.excludes,["nft"]);const map=createGalaxySnapshot(zero,900);assert.equal(map.observedEventCount,0);assert.deepEqual(new Set(map.particles.flatMap(p=>typeof p.metadata?.targetGalaxyId==="string"?[p.metadata.targetGalaxyId]:[])),new Set(["fomo","afterbell"]));assert.equal(map.particles.some(p=>["wallet","transaction","token","nft","program"].includes(p.kind)),false);assert.ok(GALAXY_ZERO_CAMERA_DISTANCE>=190);assert.equal(GALAXY_ZERO_CENTERS.length,2);assert.ok(GALAXY_ZERO_CENTERS.every(([x,y])=>Math.abs(x)<=30&&Math.abs(y)<=25));});'
if old not in text: raise SystemExit('galaxy contract anchor missing')
p.write_text(text.replace(old,new,1))

